function parseJsonLoose(text) {
  const t = String(text).replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
  try {
    return JSON.parse(t);
  } catch (e) {
    const s = t.indexOf("{");
    const end = t.lastIndexOf("}");
    if (s !== -1 && end > s) {
      try {
        return JSON.parse(t.slice(s, end + 1));
      } catch (e2) {
        /* fallthrough */
      }
    }
  }
  throw new Error("AI 返回的内容无法解析");
}

